#!/usr/bin/env python3
"""Build the shipment summary described in /app/docs/summary-format.md.

Usage: summarize.py DATA_DIR OUT_FILE
"""
import csv
import gzip
import json
import os
import re
import sys
import xml.etree.ElementTree as ET
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal, ROUND_HALF_UP

HANDOVER_ORDER = ["central", "south", "east", "river", "north", "west", "harbor", "lakeside"]

UNIT_KG = {
    "kg": Decimal(1),
    "g": Decimal("0.001"),
    "lb": Decimal("0.45359237"),
    "oz": Decimal("0.028349523125"),
}
UNIT_ALIASES = {"kgs": "kg", "kilogram": "kg", "kilograms": "kg", "gram": "g", "grams": "g",
                "lbs": "lb", "pound": "lb", "pounds": "lb", "ounce": "oz", "ounces": "oz"}

MONTHS = {m: i + 1 for i, m in enumerate(
    ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"])}

# Column names per delimited depot (used to recognise header rows).
COLUMNS = {
    "east": ["id", "type", "shipped", "gross", "net", "status", "note"],
    "harbor": ["rec", "ref", "date", "weight", "state"],
    "lakeside": ["id", "kind", "booked", "shipped", "gross_kg", "net_kg", "status"],
    "river": ["t", "ref", "shipped", "weight", "status"],
    "west": ["id", "typ", "shipped", "weight", "status", "note"],
}
DELIM = {"east": ",", "harbor": "|", "lakeside": ",", "river": "\t", "west": ";"}
# role -> column name
ROLES = {
    "east": {"id": "id", "type": "type", "shipped": "shipped", "weight": "gross", "status": "status"},
    "harbor": {"id": "ref", "type": "rec", "shipped": "date", "weight": "weight", "status": "state"},
    "lakeside": {"id": "id", "type": "kind", "shipped": "shipped", "weight": "gross_kg", "status": "status"},
    "river": {"id": "ref", "type": "t", "shipped": "shipped", "weight": "weight", "status": "status"},
    "west": {"id": "id", "type": "typ", "shipped": "shipped", "weight": "weight", "status": "status"},
}
BASE_DATE_FORM = {"east": "YMD", "harbor": "iso", "lakeside": "iso", "river": "MM/DD/YYYY",
                  "west": "DD.MM.YYYY"}
# directive names carrying the weight unit / date form, per depot
UNIT_DIRECTIVE = {"east": "unit", "river": "weight unit", "west": "weight unit"}
DATE_DIRECTIVE = {"east": "dates", "lakeside": "dates", "river": "date format"}
FIELD_UNIT = {"lakeside": "kg"}  # unit named by the weight field itself
BASE_UNIT = "kg"
DECIMAL_COMMA = {"west"}

STATUS_CODES = {"dlv": "delivered", "dll": "delivered_late", "can": "cancelled",
                "ret": "returned", "hld": "held"}

FW_LAYOUTS = {
    # name: (length, id, type, shipped, weight, status, shipped form, weight unit, weight scale)
    "FW1": dict(length=42, id=(0, 9), type=(9, 10), shipped=(10, 17), weight=(17, 25),
                status=(25, 26), dform="YYYYDDD", unit="g", scale=Decimal(1)),
    "FW2": dict(length=43, id=(1, 10), type=(0, 1), shipped=(10, 18), weight=(18, 26),
                status=(26, 27), dform="YYYYMMDD", unit="kg", scale=Decimal("0.01")),
    "FW3": dict(length=41, id=(0, 9), type=(16, 17), shipped=(9, 16), weight=(17, 24),
                status=(24, 25), dform="YYYYDDD", unit="lb", scale=Decimal("0.1")),
}
FW_STATUS = {"d": "delivered", "l": "delivered_late", "c": "cancelled", "r": "returned", "h": "held"}


class Rec:
    __slots__ = ("num", "kind", "status", "kg", "day")

    def __init__(self, num, kind, status=None, kg=None, day=None):
        self.num, self.kind, self.status, self.kg, self.day = num, kind, status, kg, day


# --------------------------------------------------------------------- bytes
def read_bytes(path):
    with open(path, "rb") as f:
        b = f.read()
    while b[:2] == b"\x1f\x8b":
        b = gzip.decompress(b)
    return b


def decode_text(b):
    if b[:3] == b"\xef\xbb\xbf":
        return b[3:].decode("utf-8", errors="replace")
    if b[:2] == b"\xff\xfe":
        return b[2:].decode("utf-16-le", errors="replace")
    if b[:2] == b"\xfe\xff":
        return b[2:].decode("utf-16-be", errors="replace")
    enc = "utf-8"
    head = b[:2000].decode("latin-1").split("\n")[:25]
    for line in head:
        m = re.match(r"\s*#\s*charset\s*:\s*([\w.\-]+)", line, re.I)
        if m:
            enc = m.group(1)
            break
    try:
        "".encode(enc)
    except LookupError:
        enc = "utf-8"
    return b.decode(enc, errors="replace")


# -------------------------------------------------------------------- values
def norm_id(s):
    if s is None:
        return None
    m = re.fullmatch(r"\s*SH[^0-9A-Za-z]*0*(\d+)\s*", str(s), re.I)
    if not m:
        return None
    return int(m.group(1))


def norm_status(s):
    if s is None:
        return None
    s = str(s).strip()
    low = s.lower()
    if low in STATUS_CODES:
        return STATUS_CODES[low]
    return re.sub(r"[\s\-]+", "_", low)


def norm_kind(s):
    s = (s or "").strip().lower()
    if s in ("", "n", "new"):
        return "new"
    if s.startswith("c") or s == "amend" or s.startswith("amend"):
        return "correction"
    if s.startswith("v"):
        return "void"
    return "new"


def norm_unit(u):
    if u is None:
        return None
    u = u.strip().lower()
    u = UNIT_ALIASES.get(u, u)
    return u if u in UNIT_KG else None


def to_kg(value, unit):
    return Decimal(value) * UNIT_KG[unit]


def parse_number(text, depot):
    """Return (Decimal, unit-or-None) for a weight string."""
    t = text.strip()
    m = re.fullmatch(r"([+-]?[\d.,\s']*\d|[+-]?[\d.,]*\.\d+)\s*([A-Za-z]+)?", t)
    if not m:
        raise ValueError("bad weight %r" % text)
    num, unit = m.group(1), m.group(2)
    num = re.sub(r"[\s']", "", num)
    if depot in DECIMAL_COMMA:
        num = num.replace(".", "").replace(",", ".")
    else:
        num = num.replace(",", "")
    u = None
    if unit:
        u = norm_unit(unit)
        if u is None:
            raise ValueError("bad unit %r" % text)
    return Decimal(num), u


def parse_day(s, form=None):
    """Return the UTC date for a ship date / time string."""
    s = s.strip()
    if not s:
        raise ValueError("empty date")
    # full time (with or without offset)
    if re.search(r"\d[T ]\d{1,2}:\d{2}", s):
        t = s.replace("Z", "+00:00").replace("z", "+00:00")
        dt = datetime.fromisoformat(t)
        if dt.tzinfo is not None:
            dt = dt.astimezone(timezone.utc)
        return dt.date()
    f = (form or "").strip()
    fu = f.upper()
    nums = re.findall(r"\d+", s)

    def ymd(y, m, d):
        return date(int(y), int(m), int(d))

    # shapes that identify themselves
    if re.fullmatch(r"\d{4}-\d{1,2}-\d{1,2}", s):
        return ymd(*nums)
    mm = re.fullmatch(r"(\d{1,2})[ \-]([A-Za-z]{3})[a-z]*[ \-,]+(\d{4})", s)
    if mm:
        return ymd(mm.group(3), MONTHS[mm.group(2).lower()], mm.group(1))
    if fu == "SERIAL" or (not f and re.fullmatch(r"\d{5}", s)):
        return date(1899, 12, 30) + timedelta(days=int(float(s)))
    if fu in ("ISO", "YMD"):
        if len(nums) == 3:
            return ymd(*nums)
    if fu == "DMY" or fu == "DD/MM/YYYY" or fu == "DD.MM.YYYY":
        if len(nums) == 3:
            return ymd(nums[2], nums[1], nums[0])
    if fu == "MM/DD/YYYY":
        if len(nums) == 3:
            return ymd(nums[2], nums[0], nums[1])
    if fu == "YYYYDDD" and re.fullmatch(r"\d{7}", s):
        return date(int(s[:4]), 1, 1) + timedelta(days=int(s[4:]) - 1)
    if fu == "YYYYMMDD" and re.fullmatch(r"\d{8}", s):
        return ymd(s[:4], s[4:6], s[6:])
    if fu in ("", "ISO", "YMD") and len(nums) == 3 and len(nums[0]) == 4:
        return ymd(*nums)
    raise ValueError("bad date %r (form %r)" % (s, form))


# ------------------------------------------------------------ delimited text
def split_logical_lines(text):
    """Yield (is_comment, line) pairs; quoted fields can span lines."""
    lines = text.split("\n")
    cur = None
    for line in lines:
        if cur is None:
            if line.endswith("\r"):
                line = line[:-1]
            if line.strip() == "":
                continue
            if line.startswith("#"):
                yield True, line
                continue
            cur = line
        else:
            cur += "\n" + line
        if cur.count('"') % 2 == 0:
            yield False, cur
            cur = None
    if cur is not None:
        yield False, cur


def parse_delimited(depot, text):
    seq = None
    directives = {}
    header = None
    names = set(COLUMNS[depot])
    delim = DELIM[depot]
    roles = ROLES[depot]
    out = []
    for is_comment, line in split_logical_lines(text):
        if is_comment:
            m = re.match(r"#\s*([^:=]+?)\s*[:=]\s*(.*)$", line)
            if m:
                name, val = m.group(1).strip().lower(), m.group(2).strip()
                directives[name] = val
                if name == "seq" and seq is None:
                    mm = re.match(r"\d+", val)
                    if mm:
                        seq = int(mm.group())
            else:
                m = re.match(r"#\s*\w+\s+export\s+seq\s*=\s*(\d+)", line)
                if m and seq is None:
                    seq = int(m.group(1))
            continue
        if delim == ",":
            try:
                fields = next(csv.reader([line]))
            except Exception:
                continue
        else:
            fields = line.split(delim)
        stripped = [f.strip() for f in fields]
        if len(stripped) >= 3 and all(f.lower() in names for f in stripped):
            header = [f.lower() for f in stripped]
            continue
        if header is None:
            continue
        col = {n: i for i, n in enumerate(header)}
        wcol = col.get(roles["weight"])
        row_unit = None
        if len(fields) == len(header) + 1 and wcol is not None:
            cand = [wcol + 1] + [i for i in range(len(fields))]
            for i in cand:
                if i < len(fields) and norm_unit(fields[i]) and fields[i].strip() != "":
                    row_unit = norm_unit(fields[i])
                    fields = fields[:i] + fields[i + 1:]
                    break
        if len(fields) != len(header):
            # a trailer or damaged row; only rows with a shipment id matter
            if len(fields) < len(header):
                fields = fields + [""] * (len(header) - len(fields))
            else:
                fields = fields[:len(header)]

        def get(role):
            i = col.get(roles[role])
            return fields[i].strip() if i is not None and i < len(fields) else ""

        num = norm_id(get("id"))
        if num is None:
            continue
        kind = norm_kind(get("type"))
        if kind == "void":
            out.append(Rec(num, kind))
            continue
        try:
            status = norm_status(get("status"))
            form = directives.get(DATE_DIRECTIVE.get(depot, ""), BASE_DATE_FORM[depot])
            form = form.split()[0] if form else form
            day = parse_day(get("shipped"), form)
            val, unit = parse_number(get("weight"), depot)
            if unit is None:
                unit = FIELD_UNIT.get(depot) or row_unit
            if unit is None:
                d = directives.get(UNIT_DIRECTIVE.get(depot, ""))
                unit = norm_unit(d.split()[0]) if d else None
            if unit is None:
                unit = BASE_UNIT
            out.append(Rec(num, kind, status, to_kg(val, unit), day))
        except Exception as e:  # keep going, report on stderr
            sys.stderr.write("warning: %s: skipped row %r: %s\n" % (depot, line[:80], e))
    return seq, out


# --------------------------------------------------------------------- south
def parse_south(text):
    seq = None
    layout = None
    out = []
    for line in text.split("\n"):
        if line.endswith("\r"):
            line = line[:-1]
        if "\x0c" in line or line.startswith("SOUTH DEPOT"):
            continue
        if line.strip() == "":
            continue
        if line.startswith("#"):
            m = re.match(r"#\s*LAYOUT\s+(\w+)", line, re.I)
            if m:
                layout = m.group(1).upper()
                continue
            m = re.match(r"#\s*SEQ\s+(\d+)", line, re.I)
            if m and seq is None:
                seq = int(m.group(1))
            continue
        lay = None
        for name, spec in FW_LAYOUTS.items():
            if spec["length"] == len(line):
                lay = spec
                break
        if lay is None:
            lay = FW_LAYOUTS.get(layout)
            if lay is None:
                continue
            line = line.ljust(lay["length"])
        try:
            def fld(k):
                a, b = lay[k]
                return line[a:b]
            num = norm_id(fld("id"))
            if num is None:
                continue
            kind = norm_kind(fld("type"))
            if kind == "void":
                out.append(Rec(num, kind))
                continue
            status = FW_STATUS.get(fld("status").strip().lower())
            if status is None:
                status = norm_status(fld("status"))
            day = parse_day(fld("shipped"), lay["dform"])
            kg = Decimal(int(fld("weight"))) * lay["scale"] * UNIT_KG[lay["unit"]]
            out.append(Rec(num, kind, status, kg, day))
        except Exception as e:
            sys.stderr.write("warning: south: skipped line %r: %s\n" % (line[:50], e))
    return seq, out


# ----------------------------------------------------------------------- xml
def parse_central(b):
    root = ET.fromstring(b)
    seq = None
    try:
        seq = int(root.attrib.get("seq", ""))
    except ValueError:
        pass
    root_unit = norm_unit(root.attrib.get("weight-unit"))
    out = []
    for s in root.iter("shipment"):
        def val(name):
            if name in s.attrib:
                return s.attrib[name]
            ch = s.find(name)
            return ch.text if ch is not None and ch.text is not None else None
        num = norm_id(s.attrib.get("id") if "id" in s.attrib else val("id"))
        if num is None:
            continue
        kind = norm_kind(s.attrib.get("type"))
        if kind == "void":
            out.append(Rec(num, kind))
            continue
        try:
            status = norm_status(val("status"))
            day = parse_day(val("shipped"), "16 Mar 2026")
            wel = s.find("weight")
            if wel is not None:
                wtext = wel.text
                unit = norm_unit(wel.attrib.get("unit"))
            else:
                wtext = s.attrib.get("weight")
                unit = norm_unit(s.attrib.get("unit"))
            w, u2 = parse_number(wtext, "central")
            unit = unit or u2 or root_unit or BASE_UNIT
            out.append(Rec(num, kind, status, to_kg(w, unit), day))
        except Exception as e:
            sys.stderr.write("warning: central: skipped %r: %s\n" % (s.attrib.get("id"), e))
    return seq, out


# --------------------------------------------------------------------- jsonl
def parse_north(text):
    seq = None
    out = []
    for line in text.split("\n"):
        line = line.strip()
        if not line:
            continue
        try:
            v = json.loads(line, parse_float=Decimal, parse_int=Decimal)
        except ValueError:
            continue
        objs = v if isinstance(v, list) else [v]
        for o in objs:
            if not isinstance(o, dict):
                continue
            if "meta" in o and isinstance(o["meta"], dict):
                if seq is None and "seq" in o["meta"]:
                    seq = int(o["meta"]["seq"])
                continue
            num = norm_id(o.get("id"))
            if num is None:
                continue
            kind = norm_kind(o.get("kind"))
            if kind == "void":
                out.append(Rec(num, kind))
                continue
            try:
                wkey = next(k for k in o if k.startswith("weight"))
                unit = norm_unit(wkey.split("_", 1)[1]) if "_" in wkey else norm_unit(o.get("unit"))
                w = o[wkey]
                if isinstance(w, str):
                    w, u2 = parse_number(w, "north")
                    unit = unit or u2
                unit = unit or BASE_UNIT
                day = parse_day(o["shipped_at"], "iso")
                out.append(Rec(num, kind, norm_status(o.get("status")), to_kg(w, unit), day))
            except Exception as e:
                sys.stderr.write("warning: north: skipped %r: %s\n" % (o.get("id"), e))
    return seq, out


# ---------------------------------------------------------------------- main
def parse_file(depot, path):
    b = read_bytes(path)
    if depot == "central":
        return parse_central(b)
    text = decode_text(b)
    if depot == "south":
        return parse_south(text)
    if depot == "north":
        return parse_north(text)
    if depot in COLUMNS:
        return parse_delimited(depot, text)
    sys.stderr.write("warning: unknown depot %r in %s\n" % (depot, path))
    return None, []


def money(d):
    return float(d.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))


def main(data_dir, out_file):
    files = []
    for e in sorted(os.scandir(data_dir), key=lambda e: e.name):
        if e.is_file():
            files.append((e.name.split("-", 1)[0], e.name, e.path))
    depots = {}
    for depot, name, path in files:
        try:
            seq, recs = parse_file(depot, path)
        except Exception as ex:
            sys.stderr.write("warning: cannot read %s: %s\n" % (path, ex))
            seq, recs = None, []
        depots.setdefault(depot, []).append((seq if seq is not None else -1, name, recs))

    corrections = resends = 0
    current = {}
    for depot, exports in depots.items():
        cur = {}
        for seq, name, recs in sorted(exports, key=lambda x: (x[0], x[1])):
            for r in recs:
                if r.kind == "new":
                    if r.num in cur:
                        resends += 1
                    else:
                        cur[r.num] = r
                elif r.kind == "correction":
                    cur[r.num] = r
                    corrections += 1
                else:
                    cur.pop(r.num, None)
                    corrections += 1
        current[depot] = cur

    order = {d: i for i, d in enumerate(HANDOVER_ORDER)}
    ranked = sorted(current, key=lambda d: (order.get(d, len(order)), d))
    owners = {}
    handovers = 0
    for depot in ranked:
        for num, r in current[depot].items():
            if num in owners:
                continue
